#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <cerrno>
#include <iostream>
#include <string>
void check(const char* label,const char* ipv4,bool dual){
  int s=socket(dual?AF_INET6:AF_INET,SOCK_DGRAM,0),option=0;
  int configured=s<0?errno:0,sent=-1,received=-1,receive_error=0;
  timeval timeout{1,0};setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,&timeout,sizeof(timeout));
  if(dual){
    if(setsockopt(s,IPPROTO_IPV6,IPV6_V6ONLY,&option,sizeof(option)))configured=errno;
    sockaddr_in6 local{};local.sin6_family=AF_INET6;local.sin6_addr=in6addr_any;
    if(bind(s,reinterpret_cast<sockaddr*>(&local),sizeof(local)))configured=errno;
    socklen_t size=sizeof(local);getsockname(s,reinterpret_cast<sockaddr*>(&local),&size);
    const auto mapped=std::string("::ffff:")+ipv4;inet_pton(AF_INET6,mapped.c_str(),&local.sin6_addr);
    sent=sendto(s,"h",1,0,reinterpret_cast<sockaddr*>(&local),sizeof(local));
  }else{
    sockaddr_in local{};local.sin_family=AF_INET;local.sin_addr.s_addr=htonl(INADDR_ANY);
    if(bind(s,reinterpret_cast<sockaddr*>(&local),sizeof(local)))configured=errno;
    socklen_t size=sizeof(local);getsockname(s,reinterpret_cast<sockaddr*>(&local),&size);
    inet_pton(AF_INET,ipv4,&local.sin_addr);
    sent=sendto(s,"h",1,0,reinterpret_cast<sockaddr*>(&local),sizeof(local));
  }
  const int send_error=sent<0?errno:0;char data{};
  received=recv(s,&data,1,0);receive_error=received<0?errno:0;close(s);
  std::cout<<"{\"case\":\""<<label<<"\",\"configured_errno\":"<<configured
    <<",\"send_bytes\":"<<sent<<",\"send_errno\":"<<send_error
    <<",\"received_exact\":"<<(received==1&&data=='h'?"true":"false")
    <<",\"receive_errno\":"<<receive_error<<"}\n";
}
int main(int argc,char** argv){if(argc!=2)return 1;
  check("ipv4-loopback","127.0.0.1",false);check("ipv4-interface-self",argv[1],false);
  check("dual-stack-loopback","127.0.0.1",true);check("dual-stack-interface-self",argv[1],true);
}
